solution.solution.cpp:
#include <type_traits>
#include <utility>

template <typename T, typename = void>
struct HasToString : std::false_type {};

template <typename T>
struct HasToString<T, std::void_t<decltype(std::declval<T>().toString())>> : std::true_type {};

unitTests:
struct Yes { std::string toString() const { return "yes"; } };
struct AlsoYes { int toString() { return 1; } };
struct No { std::string to_string() const { return "no"; } };
struct Field { int toString{}; };

static_assert(HasToString<Yes>::value, "a type with toString() should be detected");
static_assert(HasToString<AlsoYes>::value, "the return type does not matter");
static_assert(!HasToString<No>::value && !HasToString<int>::value);
static_assert(!HasToString<Field>::value, "a data member called toString is not a callable member function");

TEST("usable at run time") { CHECK(HasToString<Yes>::value); CHECK(!HasToString<double>::value); }

